export interface ClientManifestEntry {
	js?: string;
	css?: string[];
}

/** Builds the `.space/client.ts` source: typed helpers reading the manifest. */
export function generateClientSource(entries: string[]): string {
	const union =
		entries.length > 0 ? entries.map((entry) => JSON.stringify(entry)).join(" | ") : "never";
	const scriptEntries = entries.filter((entry) => !entry.endsWith(".css"));
	const scriptUnion =
		scriptEntries.length > 0
			? scriptEntries.map((entry) => JSON.stringify(entry)).join(" | ")
			: "never";
	const lines: string[] = [
		"// Generated by space. Do not edit.",
		'import { Html } from "spacefn/pages";',
		'import { clientManifest } from "./client-manifest";',
		"",
		`export type ClientEntry = ${union};`,
		`export type ClientScriptEntry = ${scriptUnion};`,
		"",
		"export function clientUrl(name: ClientEntry): string {",
		"\tconst entry = clientManifest[name as keyof typeof clientManifest];",
		'\treturn entry?.js ?? entry?.css?.[0] ?? "";',
		"}",
		"",
		"export function script(name: ClientScriptEntry): Html {",
		"\tconst entry = clientManifest[name as keyof typeof clientManifest];",
		"\tconst src = entry?.js;",
		'\tconst css = (entry?.css ?? []).map((url) => `<link rel="stylesheet" href="${url}">`).join("");',
		'\treturn new Html(`${css}${src ? `<script type="module" src="${src}"></script>` : ""}`);',
		"}",
		"",
		"export function styles(name: ClientEntry): Html {",
		"\tconst entry = clientManifest[name as keyof typeof clientManifest];",
		"\tconst urls = entry?.css ?? [];",
		'\treturn new Html(urls.map((url) => `<link rel="stylesheet" href="${url}">`).join(""));',
		"}",
		"",
	];
	return lines.join("\n");
}

/** Builds the `.space/client-manifest.ts` source. `urls` overrides the dev URLs. */
export function generateClientManifestSource(
	entries: string[],
	urls?: Record<string, { js?: string; css?: string[] }>,
): string {
	const rows = entries.map((entry) => {
		const u = urls?.[entry];
		const isCssEntry = entry.endsWith(".css");
		const js = u ? u.js : isCssEntry ? undefined : `/_client/${entry}`;
		const css = u ? u.css : isCssEntry ? [`/_client/${entry}`] : undefined;
		const properties = [
			...(js ? [`js: ${JSON.stringify(js)}`] : []),
			...(css?.length ? [`css: [${css.map((url) => JSON.stringify(url)).join(", ")}]`] : []),
		];
		if (properties.length > 0) {
			return `\t${JSON.stringify(entry)}: { ${properties.join(", ")} },`;
		}
		return `\t${JSON.stringify(entry)}: {},`;
	});
	return [
		"// Generated by space. Do not edit.",
		'import type { ClientEntry } from "./client";',
		"",
		"export const clientManifest: Record<string, { js?: string; css?: string[] }> = {",
		...rows,
		"};",
		"",
	].join("\n");
}
